    # Check if the file name contains more than three digits
    if sum(1 for char in file_name if char.isdigit()) > 3:
        return 'No'

    # Check if there is exactly one dot in the file name
    if file_name.count('.') != 1:
        return 'No'

    # Check if the part before the dot starts with a letter from the Latin alphabet
    if not file_name.split('.')[0].isalpha():
        return 'No'

    # Check if the part after the dot is 'txt', 'exe', or 'dll'
    valid_extensions = ['txt', 'exe', 'dll']
    if file_name.split('.')[-1] not in valid_extensions:
        return 'No'

    return 'Yes'

